aFamily":"TAIWAN_MOE","reference":"https://language.moe.gov.tw/001/Upload/Files/site_content/M0001/respub/download/dict_concised_2014_20260929.zip","entryId":"433800008","subjectWord":"这儿","subjectReading":"zhèr","accessedAt":"2026-10-20T04:20:10Z","accessStatus":"RETRIEVED","supports":["WORD","READING","MEANING","PART_OF_SPEECH"],"observation":"Both dictionary entries define the place where the speaker is; Vietnamese wording is editorial.","snapshotSha256":"5bab99dac44ad7a6ccdcf481e770e8aca05ede7445c4cc25b8199e0e5df64cf2"},{"provider":"Chinese Testing International syllabus 2025-11","dataFamily":"CTI_HSK_SYLLABUS","reference":"https://hsk.cn-bj.ufileos.com/3.0/%E6%96%B0%E7%89%88HSK%E8%80%83%E8%AF%95%E5%A4%A7%E7%BA%B21219.pdf","entryId":"283","subjectWord":"这儿","subjectReading":"zhèr","accessedAt":"2026-10-20T04:20:10Z","accessStatus":"RETRIEVED","supports":["HSK_LEVEL","WORD","READING"],"observation":"Ch? x?c nh?n ID, ch?, Pinyin v? c?p HSK 1; kh?ng x?c nh?n ngh?a Vi?t ho?c t? lo?i.","snapshotSha256":"ec74ce0439e837bbb15154be13e747ae798903b2fd3a331629df6c3b45504941"}],"publishHanViet":false,"publishExamples":false},"officialClassification":{"entryId":283,"syllabusVersion":"CTI_HSK_3.0_2025-11","primaryLevel":"1","word":"这儿","pinyin":"zhèr"},"decision":"APPROVE_CORE_ONLY","meaningViEditorial":true,"hanVietAndExamplesPublished":false},{"content":{"word":"这些","traditional":"這些","pinyin":"zhèxiē","pinyin_normalized":null,"meaning_vi":"nh?ng ... n?y","han_viet":null,"example_zh":null,"example_pinyin":null,"example_vi":null,"hsk_level":1,"part_of_speech":"??i t? ch? ??nh","curriculum_version":"INTERNAL_WEB_SUPPLEMENT_2026_10_20"},"contentDigest":"26e7ef80e38087ec3029ec3b6cf6ee01841c7c729cc06b3844ccc2ab5dc32055","evidence":{"curriculumVersion":"INTERNAL_WEB_SUPPLEMENT_2026_10_20","sourceVersion":"WEB-2026-10-20_CC-CEDICT-20261019_MOE-20260929","lexicalSourceRef":"Per-entry source ancestry and IDs in verification_evidence_json","meaningSourceRef":"Ngh?a ti?ng Vi?t v? t? lo?i do bi?n so?n d?a tr?n ??nh ngh?a/c?ch d?ng c? th? ?? ??i chi?u trong CC-CEDICT v? MOE; kh?ng ph?i b?n d?ch c? s?n trong ngu?n. Attribution/license: docs/Content/web-cross-check-policy.md","hanVietSourceRef":null,"exampleSourceRef":null,"hskLevel":1,"verificationMethod":"WEB_CROSS_CHECKED","verificationPolicyVersion":"WEB_CROSS_CHECKED_2026_10_20_V1","sources":[{"provider":"MDBG CC-CEDICT downloadable release","dataFamily":"CC_CEDICT","reference":"https://www.mdbg.net/chinese/export/cedict/cedict_1_0_ts_utf-8_mdbg.txt.gz","entryId":"4b7cfefba9163add2f827c6389a8690a44b898419cc1319822cfb931b090fed7","subjectWord":"这些","subjectReading":"zhèxiē","accessedAt":"2026-10-20T04:20:10Z","accessStatus":"RETRIEVED","supports":["WORD","READING","MEANING","PART_OF_SPEECH"],"observation":"Both dictionary entries identify this demonstrative plural; Vietnamese wording is editorial.","snapshotSha256":"2d42d41f75df8708d9d9b236d8ae15ecf1cef525aef8ebb8499a74cb09e1b096"},{"provider":"Taiwan MOE Concise Mandarin Dictionary 20260929","dataFamily":"TAIWAN_MOE","reference":"https://language.moe.gov.tw/001/Upload/Files/site_content/M0001/respub/download/dict_concised_2014_20260929.zip","entryId":"433800006","subjectWord":"这些","subjectReading":"zhèxiē","accessedAt":"2026-10-20T04:20:10Z","accessStatus":"RETRIEVED","supports":["WORD","READING","MEANING","PART_OF_SPEECH"],"observation":"Both dictionary entries identify this demonstrative plural; Vietnamese wording is editorial.","snapshotSha256":"5bab99dac44ad7a6ccdcf481e770e8aca05ede7445c4cc25b8199e0e5df64cf2"},{"provider":"Chinese Testing International syllabus 2025-11","dataFamily":"CTI_HSK_SYLLABUS","reference":"https://hsk.cn-bj.ufileos.com/3.0/%E6%96%B0%E7%89%88HSK%E8%80%83%E8%AF%95%E5%A4%A7%E7%BA%B21219.pdf","entryId":"284","subjectWord":"这些","subjectReading":"zhèxiē","accessedAt":"2026-10-20T04:20:10Z","accessStatus":"RETRIEVED","supports":["HSK_LEVEL","WORD","READING"],"observation":"Ch? x?c nh?n ID, ch?, Pinyin v? c?p HSK 1; kh?ng x?c nh?n ngh?a Vi?t ho?c t? lo?i.","snapshotSha256":"ec74ce0439e837bbb15154be13e747ae798903b2fd3a331629df6c3b45504941"}],"publishHanViet":false,"publishExamples":false},"officialClassification":{"entryId":284,"syllabusVersion":"CTI_HSK_3.0_2025-11","primaryLevel":"1","word":"这些","pinyin":"zhèxiē"},"decision":"APPROVE_CORE_ONLY","meaningViEditorial":true,"hanVietAndExamplesPublished":false}]$hsk2_manifest$::jsonb)
    LOOP
        content := item->'content';
        evidence := item->'evidence';
        official := item->'officialClassification';
        SELECT id INTO vocabulary_id FROM vocabulary
        WHERE word=content->>'word' AND COALESCE(pinyin, reading)=content->>'pinyin'
        ORDER BY id LIMIT 1;

        IF vocabulary_id IS NULL THEN
            INSERT INTO vocabulary (word, traditional, pinyin, reading, meaning_vi, meaning,
                part_of_speech, hsk_level, lesson_number, lesson_id, review_status,
                needs_human_check, source_ref, curriculum_version, source_version,
                lexical_source_ref, meaning_source_ref, verification_method,
                verification_policy_version, verification_evidence_json,
                han_viet, sino_vietnamese, example_zh, example_sentence,
                example_pinyin, example_reading, example_vi, example_meaning,
                han_viet_verified, example_verified, provenance_content_sha256,
                provenance_recorded_at, reviewed_at, reviewed_by)
            VALUES (content->>'word', content->>'traditional', content->>'pinyin', content->>'pinyin',
                content->>'meaning_vi', content->>'meaning_vi', content->>'part_of_speech', 1,
                1002, lesson_id, 'APPROVED', false, 'WEB_CROSS_CHECKED HSK1 batch 02',
                content->>'curriculum_version', evidence->>'sourceVersion',
                evidence->>'lexicalSourceRef', evidence->>'meaningSourceRef',
                evidence->>'verificationMethod', evidence->>'verificationPolicyVersion', evidence::text,
                NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
                false, false, item->>'contentDigest',
                (evidence->'sources'->0->>'accessedAt')::timestamptz,
                NULL, NULL)
            RETURNING id INTO vocabulary_id;
        ELSE
            SELECT pg_temp.hsk_batch_digest(v) INTO STRICT current_digest
            FROM vocabulary v WHERE v.id=vocabulary_id;
            IF current_digest IS DISTINCT FROM item->>'contentDigest'
               OR (SELECT review_status::text FROM vocabulary WHERE id=vocabulary_id) <> 'APPROVED'
               OR (SELECT verification_evidence_json FROM vocabulary WHERE id=vocabulary_id) IS DISTINCT FROM evidence::text THEN
                RAISE EXCEPTION 'Lexical identity conflicts with reviewed HSK1 batch 02: %', content->>'word';
            END IF;
        END IF;

        SELECT pg_temp.hsk_batch_digest(v) INTO STRICT current_digest
        FROM vocabulary v WHERE v.id=vocabulary_id;
        IF current_digest IS DISTINCT FROM item->>'contentDigest'
           OR (SELECT provenance_content_sha256 FROM vocabulary WHERE id=vocabulary_id) IS DISTINCT FROM item->>'contentDigest' THEN
            RAISE EXCEPTION 'Post-import vocabulary digest mismatch: %', content->>'word';
        END IF;

        INSERT INTO vocabulary_syllabus_classification
            (syllabus_version, official_entry_id, official_level, official_word, official_pinyin, vocabulary_id, content_digest)
        VALUES (official->>'syllabusVersion', (official->>'entryId')::integer, 1,
            official->>'word', official->>'pinyin', vocabulary_id, item->>'contentDigest')
        ON CONFLICT (syllabus_version, official_entry_id) DO NOTHING;

        SELECT classification.vocabulary_id, classification.content_digest,
               classification.official_word, classification.official_pinyin,
               classification.official_level
        INTO STRICT mapped_id, mapped_digest, mapped_word, mapped_pinyin, mapped_level
        FROM vocabulary_syllabus_classification classification
        WHERE classification.syllabus_version=official->>'syllabusVersion'
          AND classification.official_entry_id=(official->>'entryId')::integer;
        IF mapped_id <> vocabulary_id OR mapped_digest IS DISTINCT FROM item->>'contentDigest'
           OR mapped_word IS DISTINCT FROM official->>'word'
           OR mapped_pinyin IS DISTINCT FROM official->>'pinyin'
           OR mapped_level <> (official->>'primaryLevel')::smallint THEN
            RAISE EXCEPTION 'Official CTI ID already maps to a different content identity: %', official->>'entryId';
        END IF;
    END LOOP;
END
